#!/usr/bin/env python3
from pathlib import Path
import datetime
import py_compile
import re
import subprocess
import sys
import tempfile

BACKEND_ROOT = Path.cwd().resolve()

required = [
    BACKEND_ROOT / "app/api/v1/router.py",
    (BACKEND_ROOT / "../src/App.tsx").resolve(),
    (BACKEND_ROOT / "../src/components/admin/AdminSidebar.tsx").resolve(),
]
missing = [str(p) for p in required if not p.exists()]
if missing:
    print("ERROR: Run this from ~/Cyber_Range_Lab-/backup/backend")
    for p in missing:
        print(" -", p)
    sys.exit(1)

stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

def backup(path: Path):
    dst = path.with_name(path.name + f".before_point5_{stamp}")
    dst.write_bytes(path.read_bytes())
    print("Backup:", dst)

def write_file(relative: str, content: str):
    path = (BACKEND_ROOT / relative).resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
    print("Wrote:", path)

PAYLOAD_FILES = {'app/models/assignment_grade.py': '"""\nAssignmentGrade — professor-owned grading decision for one student on one Assignment.\n\nAutomatic score evidence remains in ScoreEvent/User*Progress.\nThis table stores only the academic grading layer and the snapshots required\nto make a published grade stable over time.\n"""\n\nfrom datetime import datetime\n\nfrom sqlalchemy import (\n    CheckConstraint,\n    Column,\n    DateTime,\n    ForeignKey,\n    Integer,\n    Numeric,\n    String,\n    Text,\n    UniqueConstraint,\n)\n\nfrom app.models.base import Base\n\n\nclass AssignmentGrade(Base):\n    __tablename__ = "assignment_grades"\n\n    __table_args__ = (\n        UniqueConstraint(\n            "assignment_id",\n            "student_id",\n            name="uq_assignment_grades_assignment_student",\n        ),\n        CheckConstraint(\n            "status IN (\'DRAFT\', \'PUBLISHED\')",\n            name="ck_assignment_grades_status",\n        ),\n        CheckConstraint(\n            "manual_adjustment >= -100 AND manual_adjustment <= 100",\n            name="ck_assignment_grades_adjustment_range",\n        ),\n    )\n\n    id = Column(Integer, primary_key=True, autoincrement=True)\n\n    assignment_id = Column(\n        Integer,\n        ForeignKey("assignments.id", ondelete="CASCADE"),\n        nullable=False,\n        index=True,\n    )\n    student_id = Column(\n        Integer,\n        ForeignKey("users.id", ondelete="CASCADE"),\n        nullable=False,\n        index=True,\n    )\n\n    # Professor-entered decision. Interpreted as percentage points.\n    manual_adjustment = Column(Numeric(6, 2), nullable=False, default=0)\n    feedback = Column(Text, nullable=True)\n\n    # Grade state.\n    status = Column(String(20), nullable=False, default="DRAFT", index=True)\n\n    # Snapshots. Drafts may be recalculated from live evidence; published rows\n    # use these stored values so publication is immutable until reopened.\n    auto_score_earned = Column(Numeric(12, 2), nullable=True)\n    score_possible = Column(Numeric(12, 2), nullable=True)\n    auto_percent = Column(Numeric(6, 2), nullable=True)\n    final_percent = Column(Numeric(6, 2), nullable=True)\n\n    graded_by = Column(\n        Integer,\n        ForeignKey("users.id", ondelete="SET NULL"),\n        nullable=True,\n        index=True,\n    )\n    published_at = Column(DateTime, nullable=True)\n\n    created_at = Column(DateTime, nullable=False, default=datetime.utcnow)\n    updated_at = Column(\n        DateTime,\n        nullable=False,\n        default=datetime.utcnow,\n        onupdate=datetime.utcnow,\n    )\n', 'app/services/gradebook_service.py': '"""\nAssignment gradebook business logic.\n\nPoint #5 scope:\n- Assignment-scoped gradebook roster.\n- Automatic score derived from immutable ScoreEvent completion evidence.\n- Professor manual adjustment and feedback.\n- Draft / publish / reopen workflow.\n- Published-grade snapshots.\n\nThis intentionally does NOT define formal rubric semantics (#6) or globally\nnormalize all platform score units (#7).\n"""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime\nfrom decimal import Decimal\nfrom typing import Dict, Iterable, List, Optional\n\nfrom fastapi import HTTPException\nfrom sqlalchemy import func\nfrom sqlalchemy.orm import Session\n\nfrom app.models.assignment import Assignment\nfrom app.models.assignment_grade import AssignmentGrade\nfrom app.models.group import Group\nfrom app.models.lab import Lab\nfrom app.models.lab_module import LabModule\nfrom app.models.score_event import ScoreEvent\nfrom app.models.user import User\nfrom app.models.user_lab_progress import UserLabProgress\nfrom app.models.user_progress import UserProgress\n\n\nMODULE_COMPLETION = "MODULE_COMPLETION"\n\n\nclass GradebookService:\n    @staticmethod\n    def _clamp_percent(value: float) -> float:\n        return round(max(0.0, min(100.0, float(value))), 2)\n\n    @staticmethod\n    def get_assignment(db: Session, assignment_id: int) -> Assignment:\n        assignment = (\n            db.query(Assignment)\n            .filter(\n                Assignment.id == assignment_id,\n                Assignment.deleted_at.is_(None),\n            )\n            .first()\n        )\n        if assignment is None:\n            raise HTTPException(status_code=404, detail="Assignment not found.")\n        return assignment\n\n    @staticmethod\n    def get_roster(db: Session, assignment: Assignment) -> List[User]:\n        if assignment.student_id is not None:\n            student = (\n                db.query(User)\n                .filter(User.id == assignment.student_id)\n                .first()\n            )\n            return [student] if student is not None else []\n\n        if assignment.group_id is not None:\n            return (\n                db.query(User)\n                .filter(\n                    User.group_id == assignment.group_id,\n                    ~User.role.ilike("%admin%"),\n                    ~User.role.ilike("%sysadmin%"),\n                )\n                .order_by(User.name.asc(), User.email.asc())\n                .all()\n            )\n\n        return []\n\n    @staticmethod\n    def get_score_possible(db: Session, assignment: Assignment) -> Dict[str, float]:\n        module_total = (\n            db.query(func.sum(LabModule.points))\n            .filter(LabModule.lab_id == assignment.lab_id)\n            .scalar()\n        )\n        module_count = (\n            db.query(func.count(LabModule.id))\n            .filter(LabModule.lab_id == assignment.lab_id)\n            .scalar()\n            or 0\n        )\n\n        if module_total and float(module_total) > 0:\n            return {\n                "score_possible": float(module_total),\n                "total_modules": int(module_count),\n                "score_source": "lab_modules",\n            }\n\n        lab = db.query(Lab).filter(Lab.id == assignment.lab_id).first()\n        if lab is not None and (lab.max_points or 0) > 0:\n            return {\n                "score_possible": float(lab.max_points),\n                "total_modules": int(module_count),\n                "score_source": "lab.max_points",\n            }\n\n        # No arbitrary denominator. Point #7 will standardize score units.\n        return {\n            "score_possible": 0.0,\n            "total_modules": int(module_count),\n            "score_source": "unavailable",\n        }\n\n    @staticmethod\n    def calculate_student_metrics(\n        db: Session,\n        assignment: Assignment,\n        student: User,\n        score_meta: Optional[Dict[str, float]] = None,\n    ) -> Dict:\n        score_meta = score_meta or GradebookService.get_score_possible(\n            db, assignment\n        )\n\n        completion_events = (\n            db.query(ScoreEvent)\n            .filter(\n                ScoreEvent.user_id == student.id,\n                ScoreEvent.assignment_id == assignment.id,\n                ScoreEvent.event_type == MODULE_COMPLETION,\n            )\n            .order_by(ScoreEvent.created_at.asc())\n            .all()\n        )\n\n        auto_score = float(\n            sum(Decimal(str(event.points or 0)) for event in completion_events)\n        )\n\n        possible = float(score_meta["score_possible"])\n        auto_percent = (\n            GradebookService._clamp_percent((auto_score / possible) * 100.0)\n            if possible > 0\n            else 0.0\n        )\n\n        ulp_rows = (\n            db.query(UserLabProgress)\n            .filter(\n                UserLabProgress.user_id == student.id,\n                UserLabProgress.assignment_id == assignment.id,\n            )\n            .all()\n        )\n        up_rows = (\n            db.query(UserProgress)\n            .filter(\n                UserProgress.user_id == str(student.id),\n                UserProgress.assignment_id == assignment.id,\n            )\n            .all()\n        )\n\n        attempts = sum(int(row.attempts or 0) for row in ulp_rows)\n        completion_time_seconds = sum(\n            int(row.time_taken_seconds or 0) for row in ulp_rows\n        )\n\n        activity_times = [\n            row.completed_at\n            for row in ulp_rows\n            if row.completed_at is not None\n        ]\n        activity_times += [\n            row.updated_at\n            for row in up_rows\n            if getattr(row, "updated_at", None) is not None\n        ]\n        activity_times += [\n            event.created_at\n            for event in completion_events\n            if event.created_at is not None\n        ]\n\n        last_activity_at = max(activity_times) if activity_times else None\n\n        completed_modules = len(\n            {\n                event.module_id\n                for event in completion_events\n                if event.module_id\n            }\n        )\n\n        total_modules = int(score_meta.get("total_modules") or 0)\n        completion_percent = (\n            round(min(100.0, (completed_modules / total_modules) * 100.0), 2)\n            if total_modules > 0\n            else None\n        )\n\n        return {\n            "auto_score_earned": round(auto_score, 2),\n            "score_possible": round(possible, 2),\n            "auto_percent": round(auto_percent, 2),\n            "completed_modules": completed_modules,\n            "total_modules": total_modules,\n            "completion_percent": completion_percent,\n            "attempts": attempts,\n            "completion_time_seconds": completion_time_seconds,\n            "last_activity_at": last_activity_at,\n            "score_source": score_meta["score_source"],\n        }\n\n    @staticmethod\n    def _grade_row(\n        db: Session,\n        assignment_id: int,\n        student_id: int,\n    ) -> Optional[AssignmentGrade]:\n        return (\n            db.query(AssignmentGrade)\n            .filter(\n                AssignmentGrade.assignment_id == assignment_id,\n                AssignmentGrade.student_id == student_id,\n            )\n            .first()\n        )\n\n    @staticmethod\n    def _serialize_row(\n        student: User,\n        metrics: Dict,\n        grade: Optional[AssignmentGrade],\n    ) -> Dict:\n        adjustment = float(grade.manual_adjustment or 0) if grade else 0.0\n\n        if grade and grade.status == "PUBLISHED":\n            auto_score = float(grade.auto_score_earned or 0)\n            possible = float(grade.score_possible or 0)\n            auto_percent = float(grade.auto_percent or 0)\n            final_percent = float(grade.final_percent or 0)\n        else:\n            auto_score = float(metrics["auto_score_earned"])\n            possible = float(metrics["score_possible"])\n            auto_percent = float(metrics["auto_percent"])\n            final_percent = GradebookService._clamp_percent(\n                auto_percent + adjustment\n            )\n\n        return {\n            "student_id": student.id,\n            "student_name": student.name or student.email.split("@")[0],\n            "email": student.email,\n            "department": getattr(student, "department", None) or "",\n            "year": getattr(student, "year", None) or "",\n            "auto_score_earned": round(auto_score, 2),\n            "score_possible": round(possible, 2),\n            "auto_percent": round(auto_percent, 2),\n            "manual_adjustment": round(adjustment, 2),\n            "final_percent": round(final_percent, 2),\n            "feedback": grade.feedback if grade and grade.feedback else "",\n            "grade_status": grade.status if grade else "DRAFT",\n            "published_at": (\n                grade.published_at.isoformat()\n                if grade and grade.published_at\n                else None\n            ),\n            "graded_by": grade.graded_by if grade else None,\n            "completed_modules": metrics["completed_modules"],\n            "total_modules": metrics["total_modules"],\n            "completion_percent": metrics["completion_percent"],\n            "attempts": metrics["attempts"],\n            "completion_time_seconds": metrics["completion_time_seconds"],\n            "last_activity_at": (\n                metrics["last_activity_at"].isoformat()\n                if metrics["last_activity_at"]\n                else None\n            ),\n            "score_source": metrics["score_source"],\n        }\n\n    @staticmethod\n    def get_gradebook(db: Session, assignment_id: int) -> Dict:\n        assignment = GradebookService.get_assignment(db, assignment_id)\n        roster = GradebookService.get_roster(db, assignment)\n        score_meta = GradebookService.get_score_possible(db, assignment)\n\n        lab = db.query(Lab).filter(Lab.id == assignment.lab_id).first()\n        group = (\n            db.query(Group).filter(Group.id == assignment.group_id).first()\n            if assignment.group_id is not None\n            else None\n        )\n\n        rows = []\n        for student in roster:\n            metrics = GradebookService.calculate_student_metrics(\n                db,\n                assignment,\n                student,\n                score_meta=score_meta,\n            )\n            grade = GradebookService._grade_row(\n                db,\n                assignment.id,\n                student.id,\n            )\n            rows.append(\n                GradebookService._serialize_row(student, metrics, grade)\n            )\n\n        avg_auto = (\n            round(sum(row["auto_percent"] for row in rows) / len(rows), 2)\n            if rows\n            else 0.0\n        )\n        avg_final = (\n            round(sum(row["final_percent"] for row in rows) / len(rows), 2)\n            if rows\n            else 0.0\n        )\n\n        return {\n            "assignment": {\n                "id": assignment.id,\n                "lab_id": assignment.lab_id,\n                "lab_title": lab.name if lab else assignment.lab_id,\n                "group_id": assignment.group_id,\n                "group_name": group.name if group else None,\n                "student_id": assignment.student_id,\n                "start_datetime": (\n                    assignment.start_datetime.isoformat()\n                    if assignment.start_datetime\n                    else None\n                ),\n                "end_datetime": (\n                    assignment.end_datetime.isoformat()\n                    if assignment.end_datetime\n                    else None\n                ),\n                "status": assignment.status,\n            },\n            "summary": {\n                "student_count": len(rows),\n                "draft_count": sum(\n                    1 for row in rows if row["grade_status"] == "DRAFT"\n                ),\n                "published_count": sum(\n                    1 for row in rows if row["grade_status"] == "PUBLISHED"\n                ),\n                "average_auto_percent": avg_auto,\n                "average_final_percent": avg_final,\n                "score_possible": score_meta["score_possible"],\n                "score_source": score_meta["score_source"],\n            },\n            "students": rows,\n        }\n\n    @staticmethod\n    def save_draft(\n        db: Session,\n        assignment_id: int,\n        student_id: int,\n        manual_adjustment: float,\n        feedback: Optional[str],\n        graded_by: int,\n    ) -> AssignmentGrade:\n        assignment = GradebookService.get_assignment(db, assignment_id)\n        roster_ids = {\n            student.id\n            for student in GradebookService.get_roster(db, assignment)\n        }\n        if student_id not in roster_ids:\n            raise HTTPException(\n                status_code=404,\n                detail="Student is not part of this assignment roster.",\n            )\n\n        grade = GradebookService._grade_row(\n            db,\n            assignment_id,\n            student_id,\n        )\n\n        if grade is not None and grade.status == "PUBLISHED":\n            raise HTTPException(\n                status_code=409,\n                detail=(\n                    "Published grades are locked. Reopen the gradebook "\n                    "before editing."\n                ),\n            )\n\n        if grade is None:\n            grade = AssignmentGrade(\n                assignment_id=assignment_id,\n                student_id=student_id,\n                status="DRAFT",\n            )\n            db.add(grade)\n\n        grade.manual_adjustment = Decimal(str(manual_adjustment))\n        grade.feedback = (feedback or "").strip() or None\n        grade.graded_by = graded_by\n        grade.status = "DRAFT"\n        grade.published_at = None\n        grade.updated_at = datetime.utcnow()\n\n        # Snapshot the current automatic evidence for auditability even while\n        # draft; GET still recalculates drafts live.\n        student = db.query(User).filter(User.id == student_id).first()\n        metrics = GradebookService.calculate_student_metrics(\n            db,\n            assignment,\n            student,\n        )\n        final_percent = GradebookService._clamp_percent(\n            metrics["auto_percent"] + float(manual_adjustment)\n        )\n\n        grade.auto_score_earned = Decimal(\n            str(metrics["auto_score_earned"])\n        )\n        grade.score_possible = Decimal(str(metrics["score_possible"]))\n        grade.auto_percent = Decimal(str(metrics["auto_percent"]))\n        grade.final_percent = Decimal(str(final_percent))\n\n        db.flush()\n        return grade\n\n    @staticmethod\n    def publish(\n        db: Session,\n        assignment_id: int,\n        graded_by: int,\n    ) -> int:\n        assignment = GradebookService.get_assignment(db, assignment_id)\n        roster = GradebookService.get_roster(db, assignment)\n        score_meta = GradebookService.get_score_possible(db, assignment)\n        now = datetime.utcnow()\n\n        published = 0\n\n        for student in roster:\n            grade = GradebookService._grade_row(\n                db,\n                assignment.id,\n                student.id,\n            )\n            if grade is None:\n                grade = AssignmentGrade(\n                    assignment_id=assignment.id,\n                    student_id=student.id,\n                    manual_adjustment=0,\n                    status="DRAFT",\n                )\n                db.add(grade)\n\n            metrics = GradebookService.calculate_student_metrics(\n                db,\n                assignment,\n                student,\n                score_meta=score_meta,\n            )\n            adjustment = float(grade.manual_adjustment or 0)\n            final_percent = GradebookService._clamp_percent(\n                metrics["auto_percent"] + adjustment\n            )\n\n            grade.auto_score_earned = Decimal(\n                str(metrics["auto_score_earned"])\n            )\n            grade.score_possible = Decimal(str(metrics["score_possible"]))\n            grade.auto_percent = Decimal(str(metrics["auto_percent"]))\n            grade.final_percent = Decimal(str(final_percent))\n            grade.graded_by = graded_by\n            grade.status = "PUBLISHED"\n            grade.published_at = now\n            grade.updated_at = now\n            published += 1\n\n        db.flush()\n        return published\n\n    @staticmethod\n    def reopen(\n        db: Session,\n        assignment_id: int,\n        graded_by: int,\n    ) -> int:\n        GradebookService.get_assignment(db, assignment_id)\n\n        rows = (\n            db.query(AssignmentGrade)\n            .filter(AssignmentGrade.assignment_id == assignment_id)\n            .all()\n        )\n\n        for grade in rows:\n            grade.status = "DRAFT"\n            grade.published_at = None\n            grade.graded_by = graded_by\n            grade.updated_at = datetime.utcnow()\n\n        db.flush()\n        return len(rows)\n', 'app/api/v1/endpoints/gradebook_api.py': '"""\nInteractive professor gradebook API.\n\nMounted at /api/v1/gradebook by app/api/v1/router.py.\n"""\n\nimport json\nfrom typing import List, Optional\n\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom pydantic import BaseModel, Field\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import get_current_admin_user, get_db\nfrom app.models.assignment import Assignment\nfrom app.models.audit_log import AuditLog\nfrom app.models.lab import Lab\nfrom app.models.user import User\nfrom app.services.gradebook_service import GradebookService\n\n\nrouter = APIRouter()\n\n\nclass GradeUpdate(BaseModel):\n    student_id: int\n    manual_adjustment: float = Field(default=0, ge=-100, le=100)\n    feedback: Optional[str] = Field(default=None, max_length=5000)\n\n\nclass GradeBatchUpdate(BaseModel):\n    grades: List[GradeUpdate]\n\n\ndef _audit(\n    db: Session,\n    actor: User,\n    action: str,\n    assignment_id: int,\n    payload: dict,\n):\n    db.add(\n        AuditLog(\n            user_id=actor.id,\n            action=action,\n            resource="AssignmentGrade",\n            resource_id=str(assignment_id),\n            performed_by=actor.email,\n            performed_by_role=actor.role,\n            status="SUCCESS",\n            new_value=json.dumps(payload, default=str),\n        )\n    )\n\n\n@router.get("/assignments")\ndef list_gradebook_assignments(\n    current_user: User = Depends(get_current_admin_user),\n    db: Session = Depends(get_db),\n):\n    """\n    Assignments available to the professor/admin gradebook.\n\n    Fine-grained organization/course authorization is intentionally deferred to\n    Point #8 RBAC; this endpoint uses the platform\'s existing admin/professor\n    dependency.\n    """\n\n    assignments = (\n        db.query(Assignment)\n        .filter(Assignment.deleted_at.is_(None))\n        .order_by(Assignment.created_at.desc(), Assignment.id.desc())\n        .all()\n    )\n\n    result = []\n    for assignment in assignments:\n        lab = db.query(Lab).filter(Lab.id == assignment.lab_id).first()\n        roster = GradebookService.get_roster(db, assignment)\n\n        result.append(\n            {\n                "assignment_id": assignment.id,\n                "lab_id": assignment.lab_id,\n                "lab_title": lab.name if lab else assignment.lab_id,\n                "group_id": assignment.group_id,\n                "student_id": assignment.student_id,\n                "student_count": len(roster),\n                "start_datetime": (\n                    assignment.start_datetime.isoformat()\n                    if assignment.start_datetime\n                    else None\n                ),\n                "end_datetime": (\n                    assignment.end_datetime.isoformat()\n                    if assignment.end_datetime\n                    else None\n                ),\n                "status": assignment.status,\n            }\n        )\n\n    return result\n\n\n@router.get("/assignments/{assignment_id}")\ndef get_gradebook(\n    assignment_id: int,\n    current_user: User = Depends(get_current_admin_user),\n    db: Session = Depends(get_db),\n):\n    return GradebookService.get_gradebook(db, assignment_id)\n\n\n@router.put("/assignments/{assignment_id}")\ndef save_gradebook_drafts(\n    assignment_id: int,\n    payload: GradeBatchUpdate,\n    current_user: User = Depends(get_current_admin_user),\n    db: Session = Depends(get_db),\n):\n    """\n    Save multiple professor edits atomically.\n\n    Published rows are locked; use /reopen before changing released grades.\n    """\n\n    try:\n        updated = 0\n\n        for item in payload.grades:\n            GradebookService.save_draft(\n                db=db,\n                assignment_id=assignment_id,\n                student_id=item.student_id,\n                manual_adjustment=item.manual_adjustment,\n                feedback=item.feedback,\n                graded_by=current_user.id,\n            )\n            updated += 1\n\n        _audit(\n            db,\n            current_user,\n            "Gradebook Draft Saved",\n            assignment_id,\n            {\n                "updated_rows": updated,\n                "student_ids": [item.student_id for item in payload.grades],\n            },\n        )\n\n        db.commit()\n\n        return {\n            "success": True,\n            "updated_rows": updated,\n            "gradebook": GradebookService.get_gradebook(\n                db,\n                assignment_id,\n            ),\n        }\n\n    except HTTPException:\n        db.rollback()\n        raise\n    except Exception as exc:\n        db.rollback()\n        raise HTTPException(\n            status_code=500,\n            detail=f"Failed to save gradebook: {exc}",\n        )\n\n\n@router.post("/assignments/{assignment_id}/publish")\ndef publish_gradebook(\n    assignment_id: int,\n    current_user: User = Depends(get_current_admin_user),\n    db: Session = Depends(get_db),\n):\n    try:\n        published = GradebookService.publish(\n            db,\n            assignment_id,\n            graded_by=current_user.id,\n        )\n\n        _audit(\n            db,\n            current_user,\n            "Gradebook Published",\n            assignment_id,\n            {"published_rows": published},\n        )\n\n        db.commit()\n\n        return {\n            "success": True,\n            "published_rows": published,\n            "gradebook": GradebookService.get_gradebook(\n                db,\n                assignment_id,\n            ),\n        }\n\n    except HTTPException:\n        db.rollback()\n        raise\n    except Exception as exc:\n        db.rollback()\n        raise HTTPException(\n            status_code=500,\n            detail=f"Failed to publish gradebook: {exc}",\n        )\n\n\n@router.post("/assignments/{assignment_id}/reopen")\ndef reopen_gradebook(\n    assignment_id: int,\n    current_user: User = Depends(get_current_admin_user),\n    db: Session = Depends(get_db),\n):\n    try:\n        reopened = GradebookService.reopen(\n            db,\n            assignment_id,\n            graded_by=current_user.id,\n        )\n\n        _audit(\n            db,\n            current_user,\n            "Gradebook Reopened",\n            assignment_id,\n            {"reopened_rows": reopened},\n        )\n\n        db.commit()\n\n        return {\n            "success": True,\n            "reopened_rows": reopened,\n            "gradebook": GradebookService.get_gradebook(\n                db,\n                assignment_id,\n            ),\n        }\n\n    except HTTPException:\n        db.rollback()\n        raise\n    except Exception as exc:\n        db.rollback()\n        raise HTTPException(\n            status_code=500,\n            detail=f"Failed to reopen gradebook: {exc}",\n        )\n', 'scratch/test_gradebook.py': '"""\nAcceptance test for Point #5 interactive gradebook.\n\nRuns inside a transaction and rolls everything back.\n\nValidates:\n- assignment-specific auto score\n- manual adjustment + feedback\n- draft grade tracks live automatic evidence\n- publish freezes a grade snapshot\n- published grade cannot be edited\n- reopen unlocks the grade\n"""\n\nfrom datetime import datetime, timedelta\nfrom decimal import Decimal\n\nfrom app.database.session import SessionLocal\nfrom app.models.assignment import Assignment\nfrom app.models.assignment_grade import AssignmentGrade\nfrom app.models.lab import Lab\nfrom app.models.lab_module import LabModule\nfrom app.models.score_event import ScoreEvent\nfrom app.models.user import User\nfrom app.services.gradebook_service import GradebookService\n\n\ndef run():\n    db = SessionLocal()\n    tx = db.begin_nested()\n\n    try:\n        print("=" * 80)\n        print("INTERACTIVE GRADEBOOK ACCEPTANCE TEST")\n        print("=" * 80)\n\n        users = (\n            db.query(User)\n            .filter(~User.role.ilike("%admin%"))\n            .order_by(User.id.asc())\n            .limit(2)\n            .all()\n        )\n        assert users, "Need at least one non-admin user."\n        student = users[0]\n        grader = users[1] if len(users) > 1 else users[0]\n\n        lab = (\n            db.query(Lab)\n            .join(LabModule, LabModule.lab_id == Lab.id)\n            .first()\n        )\n        assert lab is not None, "Need a lab with at least one LabModule."\n\n        modules = (\n            db.query(LabModule)\n            .filter(LabModule.lab_id == lab.id)\n            .order_by(LabModule.display_order.asc(), LabModule.module_number.asc())\n            .limit(2)\n            .all()\n        )\n        assert modules, "Need at least one module."\n\n        now = datetime.utcnow()\n        assignment = Assignment(\n            lab_id=lab.id,\n            student_id=student.id,\n            group_id=None,\n            start_datetime=now - timedelta(hours=1),\n            end_datetime=now + timedelta(hours=2),\n            status="Assigned",\n            assigned_by=str(grader.id),\n        )\n        db.add(assignment)\n        db.flush()\n\n        first = modules[0]\n        db.add(\n            ScoreEvent(\n                assignment_id=assignment.id,\n                user_id=student.id,\n                lab_id=lab.id,\n                track_id=first.track,\n                module_id=first.id,\n                event_type="MODULE_COMPLETION",\n                points=first.points,\n                created_at=now,\n            )\n        )\n        db.flush()\n\n        book = GradebookService.get_gradebook(db, assignment.id)\n        row = book["students"][0]\n\n        assert row["student_id"] == student.id\n        assert row["auto_score_earned"] == float(first.points)\n        assert row["grade_status"] == "DRAFT"\n        print("✅ CASE A: assignment-scoped automatic score loaded")\n\n        GradebookService.save_draft(\n            db=db,\n            assignment_id=assignment.id,\n            student_id=student.id,\n            manual_adjustment=5,\n            feedback="Strong work.",\n            graded_by=grader.id,\n        )\n        db.flush()\n\n        book = GradebookService.get_gradebook(db, assignment.id)\n        row = book["students"][0]\n\n        assert row["manual_adjustment"] == 5.0\n        assert row["feedback"] == "Strong work."\n        assert row["final_percent"] == min(\n            100.0, round(row["auto_percent"] + 5.0, 2)\n        )\n        print("✅ CASE B: professor adjustment + feedback saved as draft")\n\n        GradebookService.publish(\n            db,\n            assignment.id,\n            graded_by=grader.id,\n        )\n        db.flush()\n\n        published_book = GradebookService.get_gradebook(db, assignment.id)\n        published_row = published_book["students"][0]\n        frozen_final = published_row["final_percent"]\n        frozen_auto = published_row["auto_score_earned"]\n\n        assert published_row["grade_status"] == "PUBLISHED"\n        assert published_row["published_at"] is not None\n        print("✅ CASE C: gradebook published with stable snapshot")\n\n        # Add another completion after publication if a second module exists.\n        if len(modules) > 1:\n            second = modules[1]\n            db.add(\n                ScoreEvent(\n                    assignment_id=assignment.id,\n                    user_id=student.id,\n                    lab_id=lab.id,\n                    track_id=second.track,\n                    module_id=second.id,\n                    event_type="MODULE_COMPLETION",\n                    points=second.points,\n                    created_at=now + timedelta(minutes=5),\n                )\n            )\n            db.flush()\n\n            still_published = GradebookService.get_gradebook(\n                db, assignment.id\n            )["students"][0]\n            assert still_published["auto_score_earned"] == frozen_auto\n            assert still_published["final_percent"] == frozen_final\n            print("✅ CASE D: published grade did not drift after new evidence")\n        else:\n            print("⚠️ CASE D skipped: lab only has one module")\n\n        edit_blocked = False\n        try:\n            GradebookService.save_draft(\n                db=db,\n                assignment_id=assignment.id,\n                student_id=student.id,\n                manual_adjustment=10,\n                feedback="Should be blocked",\n                graded_by=grader.id,\n            )\n        except Exception:\n            edit_blocked = True\n\n        assert edit_blocked\n        print("✅ CASE E: published grade is locked")\n\n        GradebookService.reopen(\n            db,\n            assignment.id,\n            graded_by=grader.id,\n        )\n        db.flush()\n\n        reopened = GradebookService.get_gradebook(\n            db, assignment.id\n        )["students"][0]\n        assert reopened["grade_status"] == "DRAFT"\n\n        if len(modules) > 1:\n            assert reopened["auto_score_earned"] >= frozen_auto\n\n        print("✅ CASE F: reopen returns grade to live draft state")\n\n        print("=" * 80)\n        print("✅ ALL INTERACTIVE GRADEBOOK TESTS PASSED")\n        print("=" * 80)\n\n    finally:\n        tx.rollback()\n        db.rollback()\n        db.close()\n        print("Test transaction rolled back.")\n\n\nif __name__ == "__main__":\n    run()\n', '../src/pages/admin/GradebookPage.tsx': 'import React, { useEffect, useMemo, useState } from \'react\';\nimport {\n  BookOpenCheck,\n  CheckCircle2,\n  ChevronDown,\n  Lock,\n  RefreshCcw,\n  Save,\n  Search,\n  Send,\n  Unlock,\n  Users,\n} from \'lucide-react\';\n\ntype AssignmentOption = {\n  assignment_id: number;\n  lab_id: string;\n  lab_title: string;\n  group_id: number | null;\n  student_id: number | null;\n  student_count: number;\n  start_datetime: string | null;\n  end_datetime: string | null;\n  status: string;\n};\n\ntype GradeRow = {\n  student_id: number;\n  student_name: string;\n  email: string;\n  department: string;\n  year: string;\n  auto_score_earned: number;\n  score_possible: number;\n  auto_percent: number;\n  manual_adjustment: number;\n  final_percent: number;\n  feedback: string;\n  grade_status: \'DRAFT\' | \'PUBLISHED\';\n  published_at: string | null;\n  graded_by: number | null;\n  completed_modules: number;\n  total_modules: number;\n  completion_percent: number | null;\n  attempts: number;\n  completion_time_seconds: number;\n  last_activity_at: string | null;\n  score_source: string;\n};\n\ntype GradebookData = {\n  assignment: {\n    id: number;\n    lab_id: string;\n    lab_title: string;\n    group_id: number | null;\n    group_name: string | null;\n    student_id: number | null;\n    start_datetime: string | null;\n    end_datetime: string | null;\n    status: string;\n  };\n  summary: {\n    student_count: number;\n    draft_count: number;\n    published_count: number;\n    average_auto_percent: number;\n    average_final_percent: number;\n    score_possible: number;\n    score_source: string;\n  };\n  students: GradeRow[];\n};\n\nconst clampPercent = (value: number) =>\n  Math.max(0, Math.min(100, Math.round(value * 100) / 100));\n\nconst formatDate = (value: string | null) => {\n  if (!value) return \'—\';\n  const d = new Date(value);\n  return Number.isNaN(d.getTime()) ? value : d.toLocaleString();\n};\n\nconst formatDuration = (seconds: number) => {\n  if (!seconds) return \'—\';\n  const h = Math.floor(seconds / 3600);\n  const m = Math.floor((seconds % 3600) / 60);\n  return h > 0 ? `${h}h ${m}m` : `${m}m`;\n};\n\nexport const GradebookPage: React.FC = () => {\n  const [assignments, setAssignments] = useState<AssignmentOption[]>([]);\n  const [selectedAssignmentId, setSelectedAssignmentId] = useState<number | null>(null);\n  const [gradebook, setGradebook] = useState<GradebookData | null>(null);\n  const [draftRows, setDraftRows] = useState<Record<number, GradeRow>>({});\n  const [search, setSearch] = useState(\'\');\n  const [loadingAssignments, setLoadingAssignments] = useState(true);\n  const [loadingGradebook, setLoadingGradebook] = useState(false);\n  const [saving, setSaving] = useState(false);\n  const [publishing, setPublishing] = useState(false);\n  const [error, setError] = useState(\'\');\n  const [toast, setToast] = useState(\'\');\n\n  const token = localStorage.getItem(\'token\');\n  const authHeaders: Record<string, string> = token\n    ? { Authorization: `Bearer ${token}` }\n    : {};\n\n  const showToast = (message: string) => {\n    setToast(message);\n    window.setTimeout(() => setToast(\'\'), 3000);\n  };\n\n  const loadAssignments = async () => {\n    setLoadingAssignments(true);\n    setError(\'\');\n    try {\n      const res = await fetch(\'/api/v1/gradebook/assignments\', {\n        headers: authHeaders,\n      });\n      if (!res.ok) {\n        const body = await res.json().catch(() => ({}));\n        throw new Error(body.detail || \'Failed to load assignments.\');\n      }\n\n      const data: AssignmentOption[] = await res.json();\n      setAssignments(data);\n\n      if (data.length > 0 && selectedAssignmentId === null) {\n        setSelectedAssignmentId(data[0].assignment_id);\n      }\n    } catch (err: any) {\n      setError(err.message || \'Failed to load assignments.\');\n    } finally {\n      setLoadingAssignments(false);\n    }\n  };\n\n  const loadGradebook = async (assignmentId: number) => {\n    setLoadingGradebook(true);\n    setError(\'\');\n    try {\n      const res = await fetch(`/api/v1/gradebook/assignments/${assignmentId}`, {\n        headers: authHeaders,\n      });\n      if (!res.ok) {\n        const body = await res.json().catch(() => ({}));\n        throw new Error(body.detail || \'Failed to load gradebook.\');\n      }\n\n      const data: GradebookData = await res.json();\n      setGradebook(data);\n\n      const byId: Record<number, GradeRow> = {};\n      data.students.forEach((row) => {\n        byId[row.student_id] = { ...row };\n      });\n      setDraftRows(byId);\n    } catch (err: any) {\n      setError(err.message || \'Failed to load gradebook.\');\n      setGradebook(null);\n      setDraftRows({});\n    } finally {\n      setLoadingGradebook(false);\n    }\n  };\n\n  useEffect(() => {\n    loadAssignments();\n  }, []);\n\n  useEffect(() => {\n    if (selectedAssignmentId !== null) {\n      loadGradebook(selectedAssignmentId);\n    }\n  }, [selectedAssignmentId]);\n\n  const rows = useMemo(() => {\n    if (!gradebook) return [];\n\n    const query = search.trim().toLowerCase();\n    return gradebook.students\n      .map((base) => draftRows[base.student_id] || base)\n      .filter((row) => {\n        if (!query) return true;\n        return (\n          row.student_name.toLowerCase().includes(query) ||\n          row.email.toLowerCase().includes(query) ||\n          (row.department || \'\').toLowerCase().includes(query)\n        );\n      });\n  }, [gradebook, draftRows, search]);\n\n  const allPublished =\n    gradebook !== null &&\n    gradebook.students.length > 0 &&\n    gradebook.students.every((row) => row.grade_status === \'PUBLISHED\');\n\n  const anyPublished =\n    gradebook?.students.some((row) => row.grade_status === \'PUBLISHED\') || false;\n\n  const updateRow = (\n    studentId: number,\n    patch: Partial<Pick<GradeRow, \'manual_adjustment\' | \'feedback\'>>\n  ) => {\n    setDraftRows((current) => {\n      const existing = current[studentId];\n      if (!existing || existing.grade_status === \'PUBLISHED\') return current;\n\n      const adjustment =\n        patch.manual_adjustment !== undefined\n          ? patch.manual_adjustment\n          : existing.manual_adjustment;\n\n      const finalPercent = clampPercent(existing.auto_percent + adjustment);\n\n      return {\n        ...current,\n        [studentId]: {\n          ...existing,\n          ...patch,\n          manual_adjustment: adjustment,\n          final_percent: finalPercent,\n        },\n      };\n    });\n  };\n\n  const saveDrafts = async () => {\n    if (!gradebook || selectedAssignmentId === null) return;\n\n    const editableRows = Object.values(draftRows).filter(\n      (row) => row.grade_status !== \'PUBLISHED\'\n    );\n\n    setSaving(true);\n    setError(\'\');\n    try {\n      const res = await fetch(\n        `/api/v1/gradebook/assignments/${selectedAssignmentId}`,\n        {\n          method: \'PUT\',\n          headers: {\n            ...authHeaders,\n            \'Content-Type\': \'application/json\',\n          },\n          body: JSON.stringify({\n            grades: editableRows.map((row) => ({\n              student_id: row.student_id,\n              manual_adjustment: Number(row.manual_adjustment || 0),\n              feedback: row.feedback || \'\',\n            })),\n          }),\n        }\n      );\n\n      const body = await res.json().catch(() => ({}));\n      if (!res.ok) {\n        throw new Error(body.detail || \'Failed to save gradebook.\');\n      }\n\n      setGradebook(body.gradebook);\n      const byId: Record<number, GradeRow> = {};\n      body.gradebook.students.forEach((row: GradeRow) => {\n        byId[row.student_id] = { ...row };\n      });\n      setDraftRows(byId);\n      showToast(`Saved ${body.updated_rows} draft grade${body.updated_rows === 1 ? \'\' : \'s\'}.`);\n    } catch (err: any) {\n      setError(err.message || \'Failed to save gradebook.\');\n    } finally {\n      setSaving(false);\n    }\n  };\n\n  const publishAll = async () => {\n    if (selectedAssignmentId === null) return;\n\n    const confirmed = window.confirm(\n      \'Publish all grades for this assignment? Published grades are frozen until you reopen the gradebook.\'\n    );\n    if (!confirmed) return;\n\n    setPublishing(true);\n    setError(\'\');\n    try {\n      // Save current draft edits first.\n      if (!allPublished) {\n        const editableRows = Object.values(draftRows).filter(\n          (row) => row.grade_status !== \'PUBLISHED\'\n        );\n\n        const saveRes = await fetch(\n          `/api/v1/gradebook/assignments/${selectedAssignmentId}`,\n          {\n            method: \'PUT\',\n            headers: {\n              ...authHeaders,\n              \'Content-Type\': \'application/json\',\n            },\n            body: JSON.stringify({\n              grades: editableRows.map((row) => ({\n                student_id: row.student_id,\n                manual_adjustment: Number(row.manual_adjustment || 0),\n                feedback: row.feedback || \'\',\n              })),\n            }),\n          }\n        );\n\n        if (!saveRes.ok) {\n          const saveBody = await saveRes.json().catch(() => ({}));\n          throw new Error(saveBody.detail || \'Could not save drafts before publishing.\');\n        }\n      }\n\n      const res = await fetch(\n        `/api/v1/gradebook/assignments/${selectedAssignmentId}/publish`,\n        {\n          method: \'POST\',\n          headers: authHeaders,\n        }\n      );\n\n      const body = await res.json().catch(() => ({}));\n      if (!res.ok) {\n        throw new Error(body.detail || \'Failed to publish gradebook.\');\n      }\n\n      setGradebook(body.gradebook);\n      const byId: Record<number, GradeRow> = {};\n      body.gradebook.students.forEach((row: GradeRow) => {\n        byId[row.student_id] = { ...row };\n      });\n      setDraftRows(byId);\n      showToast(`Published ${body.published_rows} grade${body.published_rows === 1 ? \'\' : \'s\'}.`);\n    } catch (err: any) {\n      setError(err.message || \'Failed to publish gradebook.\');\n    } finally {\n      setPublishing(false);\n    }\n  };\n\n  const reopen = async () => {\n    if (selectedAssignmentId === null) return;\n\n    const confirmed = window.confirm(\n      \'Reopen this gradebook? Published grades will return to draft state and begin reflecting current automatic scoring again.\'\n    );\n    if (!confirmed) return;\n\n    setPublishing(true);\n    setError(\'\');\n    try {\n      const res = await fetch(\n        `/api/v1/gradebook/assignments/${selectedAssignmentId}/reopen`,\n        {\n          method: \'POST\',\n          headers: authHeaders,\n        }\n      );\n\n      const body = await res.json().catch(() => ({}));\n      if (!res.ok) {\n        throw new Error(body.detail || \'Failed to reopen gradebook.\');\n      }\n\n      setGradebook(body.gradebook);\n      const byId: Record<number, GradeRow> = {};\n      body.gradebook.students.forEach((row: GradeRow) => {\n        byId[row.student_id] = { ...row };\n      });\n      setDraftRows(byId);\n      showToast(\'Gradebook reopened.\');\n    } catch (err: any) {\n      setError(err.message || \'Failed to reopen gradebook.\');\n    } finally {\n      setPublishing(false);\n    }\n  };\n\n  return (\n    <div className="space-y-6 text-xs text-slate-800 dark:text-slate-200">\n      <div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between">\n        <div>\n          <div className="flex items-center gap-2">\n            <BookOpenCheck className="h-5 w-5 text-blue-600" />\n            <h1 className="text-xl font-black text-slate-950 dark:text-white">\n              Professor Gradebook\n            </h1>\n          </div>\n          <p className="mt-1 max-w-3xl text-slate-500">\n            Review automatic assignment scores, apply percentage-point adjustments,\n            leave feedback, and publish stable final grades.\n          </p>\n        </div>\n\n        <button\n          type="button"\n          onClick={() => {\n            loadAssignments();\n            if (selectedAssignmentId !== null) {\n              loadGradebook(selectedAssignmentId);\n            }\n          }}\n          className="inline-flex items-center gap-2 self-start rounded-xl border border-slate-200 bg-white px-3 py-2 font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200"\n        >\n          <RefreshCcw className="h-4 w-4" />\n          Refresh\n        </button>\n      </div>\n\n      <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-slate-900">\n        <label className="mb-2 block text-[10px] font-black uppercase tracking-wide text-slate-400">\n          Assignment\n        </label>\n        <div className="relative">\n          <select\n            value={selectedAssignmentId ?? \'\'}\n            onChange={(e) =>\n              setSelectedAssignmentId(e.target.value ? Number(e.target.value) : null)\n            }\n            disabled={loadingAssignments}\n            className="w-full appearance-none rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 pr-10 font-bold text-slate-800 outline-none focus:border-blue-500 dark:border-slate-700 dark:bg-slate-800 dark:text-white"\n          >\n            {assignments.length === 0 && <option value="">No assignments available</option>}\n            {assignments.map((assignment) => (\n              <option key={assignment.assignment_id} value={assignment.assignment_id}>\n                #{assignment.assignment_id} — {assignment.lab_title} — {assignment.student_count} student{assignment.student_count === 1 ? \'\' : \'s\'}\n              </option>\n            ))}\n          </select>\n          <ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />\n        </div>\n      </div>\n\n      {error && (\n        <div className="rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 font-bold text-rose-700 dark:border-rose-900/50 dark:bg-rose-950/30 dark:text-rose-300">\n          {error}\n        </div>\n      )}\n\n      {loadingGradebook && (\n        <div className="rounded-2xl border border-slate-200 bg-white py-16 text-center font-bold text-slate-400 dark:border-slate-800 dark:bg-slate-900">\n          Loading gradebook…\n        </div>\n      )}\n\n      {!loadingGradebook && gradebook && (\n        <>\n          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">\n            {[\n              {\n                label: \'Students\',\n                value: gradebook.summary.student_count,\n                icon: Users,\n              },\n              {\n                label: \'Average Auto\',\n                value: `${gradebook.summary.average_auto_percent}%`,\n                icon: BookOpenCheck,\n              },\n              {\n                label: \'Average Final\',\n                value: `${gradebook.summary.average_final_percent}%`,\n                icon: CheckCircle2,\n              },\n              {\n                label: \'Draft\',\n                value: gradebook.summary.draft_count,\n                icon: Unlock,\n              },\n              {\n                label: \'Published\',\n                value: gradebook.summary.published_count,\n                icon: Lock,\n              },\n            ].map(({ label, value, icon: Icon }) => (\n              <div\n                key={label}\n                className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900"\n              >\n                <div className="flex items-center justify-between">\n                  <span className="text-[10px] font-black uppercase text-slate-400">\n                    {label}\n                  </span>\n                  <Icon className="h-4 w-4 text-slate-400" />\n                </div>\n                <div className="mt-2 text-lg font-black text-slate-950 dark:text-white">\n                  {value}\n                </div>\n              </div>\n            ))}\n          </div>\n\n          <div className="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">\n            <div className="flex flex-col gap-3 border-b border-slate-100 p-4 dark:border-slate-800 lg:flex-row lg:items-center lg:justify-between">\n              <div>\n                <h2 className="font-black text-slate-950 dark:text-white">\n                  {gradebook.assignment.lab_title}\n                </h2>\n                <p className="mt-1 text-slate-500">\n                  Assignment #{gradebook.assignment.id}\n                  {gradebook.assignment.group_name\n                    ? ` • ${gradebook.assignment.group_name}`\n                    : \'\'}\n                  {\' • \'}\n                  {formatDate(gradebook.assignment.start_datetime)}\n                  {\' → \'}\n                  {formatDate(gradebook.assignment.end_datetime)}\n                </p>\n                <p className="mt-1 text-[10px] font-semibold text-slate-400">\n                  Automatic denominator: {gradebook.summary.score_possible || \'Unavailable\'} points\n                  {\' • \'}\n                  source: {gradebook.summary.score_source}\n                </p>\n              </div>\n\n              <div className="flex flex-wrap gap-2">\n                {anyPublished ? (\n                  <button\n                    type="button"\n                    onClick={reopen}\n                    disabled={publishing}\n                    className="inline-flex items-center gap-2 rounded-xl border border-amber-300 bg-amber-50 px-3 py-2 font-black text-amber-700 hover:bg-amber-100 disabled:opacity-50"\n                  >\n                    <Unlock className="h-4 w-4" />\n                    Reopen Gradebook\n                  </button>\n                ) : (\n                  <>\n                    <button\n                      type="button"\n                      onClick={saveDrafts}\n                      disabled={saving}\n                      className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 font-black text-slate-700 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-200"\n                    >\n                      <Save className="h-4 w-4" />\n                      {saving ? \'Saving…\' : \'Save Drafts\'}\n                    </button>\n                    <button\n                      type="button"\n                      onClick={publishAll}\n                      disabled={publishing || gradebook.students.length === 0}\n                      className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-3 py-2 font-black text-white hover:bg-blue-700 disabled:opacity-50"\n                    >\n                      <Send className="h-4 w-4" />\n                      {publishing ? \'Publishing…\' : \'Publish All\'}\n                    </button>\n                  </>\n                )}\n              </div>\n            </div>\n\n            <div className="border-b border-slate-100 p-4 dark:border-slate-800">\n              <div className="relative max-w-md">\n                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />\n                <input\n                  value={search}\n                  onChange={(e) => setSearch(e.target.value)}\n                  placeholder="Search students…"\n                  className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pl-9 pr-3 outline-none focus:border-blue-500 dark:border-slate-700 dark:bg-slate-800"\n                />\n              </div>\n            </div>\n\n            <div className="overflow-x-auto">\n              <table className="min-w-[1180px] w-full border-collapse text-left">\n                <thead>\n                  <tr className="border-b border-slate-200 bg-slate-50 text-[10px] font-black uppercase text-slate-400 dark:border-slate-700 dark:bg-slate-800/60">\n                    <th className="p-3">Student</th>\n                    <th className="p-3 text-center">Progress</th>\n                    <th className="p-3 text-center">Auto Score</th>\n                    <th className="p-3 text-center">Auto %</th>\n                    <th className="p-3 text-center">Adjustment</th>\n                    <th className="p-3 text-center">Final %</th>\n                    <th className="p-3">Feedback</th>\n                    <th className="p-3 text-center">Attempts</th>\n                    <th className="p-3 text-center">Time</th>\n                    <th className="p-3 text-center">Status</th>\n                  </tr>\n                </thead>\n                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">\n                  {rows.map((row) => {\n                    const locked = row.grade_status === \'PUBLISHED\';\n                    return (\n                      <tr key={row.student_id} className="align-top hover:bg-slate-50/60 dark:hover:bg-slate-800/20">\n                        <td className="p-3">\n                          <div className="font-black text-slate-950 dark:text-white">\n                            {row.student_name}\n                          </div>\n                          <div className="mt-0.5 text-[10px] text-slate-500">\n                            {row.email}\n                          </div>\n                          {(row.department || row.year) && (\n                            <div className="mt-0.5 text-[10px] text-slate-400">\n                              {[row.department, row.year].filter(Boolean).join(\' • \')}\n                            </div>\n                          )}\n                        </td>\n\n                        <td className="p-3 text-center">\n                          <div className="font-black">\n                            {row.completion_percent === null\n                              ? \'—\'\n                              : `${row.completion_percent}%`}\n                          </div>\n                          <div className="mt-0.5 text-[10px] text-slate-400">\n                            {row.completed_modules}\n                            {row.total_modules > 0 ? ` / ${row.total_modules}` : \'\'} modules\n                          </div>\n                        </td>\n\n                        <td className="p-3 text-center font-black">\n                          {row.auto_score_earned}\n                          <span className="font-semibold text-slate-400">\n                            {\' / \'}\n                            {row.score_possible || \'—\'}\n                          </span>\n                        </td>\n\n                        <td className="p-3 text-center font-black text-blue-600 dark:text-blue-400">\n                          {row.auto_percent}%\n                        </td>\n\n                        <td className="p-3 text-center">\n                          <input\n                            type="number"\n                            min={-100}\n                            max={100}\n                            step="0.5"\n                            value={row.manual_adjustment}\n                            disabled={locked}\n                            onChange={(e) =>\n                              updateRow(row.student_id, {\n                                manual_adjustment: Math.max(\n                                  -100,\n                                  Math.min(100, Number(e.target.value || 0))\n                                ),\n                              })\n                            }\n                            className="w-20 rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-center font-black outline-none focus:border-blue-500 disabled:bg-slate-100 disabled:text-slate-400 dark:border-slate-700 dark:bg-slate-800 dark:disabled:bg-slate-850"\n                          />\n                          <div className="mt-1 text-[9px] text-slate-400">percentage points</div>\n                        </td>\n\n                        <td className="p-3 text-center">\n                          <span className="inline-flex rounded-lg bg-emerald-50 px-2.5 py-1 font-black text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">\n                            {row.final_percent}%\n                          </span>\n                        </td>\n\n                        <td className="p-3">\n                          <textarea\n                            rows={2}\n                            value={row.feedback}\n                            disabled={locked}\n                            onChange={(e) =>\n                              updateRow(row.student_id, {\n                                feedback: e.target.value,\n                              })\n                            }\n                            placeholder="Professor feedback…"\n                            className="min-w-[220px] w-full resize-y rounded-lg border border-slate-200 bg-white px-2.5 py-2 outline-none focus:border-blue-500 disabled:bg-slate-100 disabled:text-slate-400 dark:border-slate-700 dark:bg-slate-800 dark:disabled:bg-slate-850"\n                          />\n                        </td>\n\n                        <td className="p-3 text-center font-bold">{row.attempts || \'—\'}</td>\n                        <td className="p-3 text-center text-slate-500">\n                          {formatDuration(row.completion_time_seconds)}\n                        </td>\n\n                        <td className="p-3 text-center">\n                          <span\n                            className={`inline-flex items-center gap-1 rounded-full border px-2 py-1 text-[9px] font-black ${\n                              locked\n                                ? \'border-emerald-200 bg-emerald-50 text-emerald-700\'\n                                : \'border-amber-200 bg-amber-50 text-amber-700\'\n                            }`}\n                          >\n                            {locked ? (\n                              <Lock className="h-3 w-3" />\n                            ) : (\n                              <Unlock className="h-3 w-3" />\n                            )}\n                            {row.grade_status}\n                          </span>\n                          {row.published_at && (\n                            <div className="mt-1 whitespace-nowrap text-[9px] text-slate-400">\n                              {formatDate(row.published_at)}\n                            </div>\n                          )}\n                        </td>\n                      </tr>\n                    );\n                  })}\n\n                  {rows.length === 0 && (\n                    <tr>\n                      <td colSpan={10} className="p-12 text-center font-bold text-slate-400">\n                        No students match this gradebook.\n                      </td>\n                    </tr>\n                  )}\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </>\n      )}\n\n      {toast && (\n        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-2 rounded-xl bg-slate-950 px-4 py-3 font-bold text-white shadow-xl">\n          <CheckCircle2 className="h-4 w-4 text-emerald-400" />\n          {toast}\n        </div>\n      )}\n    </div>\n  );\n};\n'}
